#!/usr/bin/env python3
"""Generate test fixtures for @stdlib/blas/base/ctrsv.

Uses SciPy's BLAS ctrsv to compute reference expected outputs for all
combinations of order, uplo, trans, diag, and various stride/offset configs.

Usage:
    python3 -m venv .venv && source .venv/bin/activate
    pip install numpy scipy
    python3 runner.py
"""

import json
import os
import numpy as np
from scipy.linalg.blas import ctrsv as sp_ctrsv


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def interleave(arr):
    """Complex64 array -> interleaved float32 list [re0, im0, re1, im1, ...]."""
    out = []
    for z in arr:
        out.append(float(np.float32(z.real)))
        out.append(float(np.float32(z.imag)))
    return out


def mat_to_list(mat):
    """2-D complex matrix -> list-of-lists of interleaved reals (for A_mat)."""
    rows = []
    for i in range(mat.shape[0]):
        row = []
        for j in range(mat.shape[1]):
            row.append(float(np.float32(mat[i, j].real)))
            row.append(float(np.float32(mat[i, j].imag)))
        rows.append(row)
    return rows


def layout_matrix(mat, order, sa1, sa2, oa):
    """Lay out a 2-D complex matrix into a flat interleaved float32 list
    using the given strides and offset (all in complex-element units).

    For row-major: element (i, j) is at complex index oa + i*sa1 + j*sa2
    For column-major: element (i, j) is at complex index oa + i*sa1 + j*sa2
    (strides already encode the order)

    Returns interleaved float32 list.
    """
    N = mat.shape[0]
    # Compute the maximum index needed
    max_idx = oa
    for i in range(N):
        for j in range(N):
            idx = oa + i * sa1 + j * sa2
            if idx > max_idx:
                max_idx = idx
    total = max_idx + 1

    buf = [0.0] * (total * 2)
    for i in range(N):
        for j in range(N):
            idx = oa + i * sa1 + j * sa2
            z = mat[i, j]
            buf[idx * 2] = float(np.float32(z.real))
            buf[idx * 2 + 1] = float(np.float32(z.imag))
    return buf


def solve_ctrsv(A, x, uplo, trans, diag):
    """Solve using SciPy's ctrsv BLAS binding (column-major Fortran order)."""
    lower = 1 if uplo == 'lower' else 0
    trans_map = {'no-transpose': 0, 'transpose': 1, 'conjugate-transpose': 2}
    trans_flag = trans_map[trans]
    unit_diag = 1 if diag == 'unit' else 0

    A_f = np.asfortranarray(A.astype(np.complex64))
    x_copy = x.astype(np.complex64).copy()
    result = sp_ctrsv(A_f, x_copy, lower=lower, trans=trans_flag,
                      diag=unit_diag, overwrite_x=1)
    return np.array(result, dtype=np.complex64)


def fmt_list(lst):
    """Format a flat list on one line: [ 1.0, 2.0, 3.0 ]."""
    return '[ ' + ', '.join(_fmt_num(v) for v in lst) + ' ]'


def fmt_mat(mat):
    """Format A_mat as multi-line with each row on its own line."""
    lines = []
    lines.append('[')
    for i, row in enumerate(mat):
        row_str = '    [ ' + ', '.join(_fmt_num(v) for v in row) + ' ]'
        if i < len(mat) - 1:
            row_str += ','
        lines.append(row_str)
    lines.append('  ]')
    return '\n'.join(lines)


def _fmt_num(v):
    """Format a number: strip trailing zeros but keep '.0' for floats."""
    if isinstance(v, float):
        if v == int(v) and abs(v) < 1e15:
            return f"{int(v)}.0"
        return repr(v)
    return str(v)


def write_fixture(filename, data):
    """Write a fixture dict as JSON with compact array formatting."""
    fixtures_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                '..', 'test', 'fixtures')
    filepath = os.path.join(fixtures_dir, filename)

    lines = ['{']
    keys = list(data.keys())
    for idx, key in enumerate(keys):
        val = data[key]
        comma = ',' if idx < len(keys) - 1 else ''

        if key == 'A_mat':
            lines.append(f'  "{key}": {fmt_mat(val)}{comma}')
        elif isinstance(val, list):
            lines.append(f'  "{key}": {fmt_list(val)}{comma}')
        elif isinstance(val, str):
            lines.append(f'  "{key}": "{val}"{comma}')
        elif isinstance(val, int):
            lines.append(f'  "{key}": {val}{comma}')
        elif isinstance(val, float):
            lines.append(f'  "{key}": {_fmt_num(val)}{comma}')
        else:
            lines.append(f'  "{key}": {json.dumps(val)}{comma}')

    lines.append('}')
    lines.append('')  # trailing newline

    with open(filepath, 'w') as f:
        f.write('\n'.join(lines))
    print(f"  Written: {filename}")


# ---------------------------------------------------------------------------
# Standard 3x3 triangular matrices
# ---------------------------------------------------------------------------

def make_lower():
    return np.array([
        [1+2j, 0+0j, 0+0j],
        [3+4j, 7+8j, 0+0j],
        [5+6j, 9+10j, 11+12j],
    ], dtype=np.complex64)


def make_upper():
    return np.array([
        [1+2j, 3+4j, 5+6j],
        [0+0j, 7+8j, 9+10j],
        [0+0j, 0+0j, 11+12j],
    ], dtype=np.complex64)


def make_lower_unit():
    return np.array([
        [1+0j, 0+0j, 0+0j],
        [3+4j, 1+0j, 0+0j],
        [5+6j, 9+10j, 1+0j],
    ], dtype=np.complex64)


def make_upper_unit():
    return np.array([
        [1+0j, 3+4j, 5+6j],
        [0+0j, 1+0j, 9+10j],
        [0+0j, 0+0j, 1+0j],
    ], dtype=np.complex64)


X_INIT = np.array([1+2j, 3+4j, 5+6j], dtype=np.complex64)


# ---------------------------------------------------------------------------
# Branch fixtures
# ---------------------------------------------------------------------------

def gen_branch_fixtures():
    """Generate branch fixtures for all uplo/trans/diag combos."""

    configs = [
        ('lower', 'no-transpose', 'non-unit', make_lower, 'l_nt_nu'),
        ('lower', 'no-transpose', 'unit', make_lower_unit, 'l_nt_u'),
        ('lower', 'transpose', 'non-unit', make_lower, 'l_t_nu'),
        ('lower', 'transpose', 'unit', make_lower_unit, 'l_t_u'),
        ('lower', 'conjugate-transpose', 'non-unit', make_lower, 'l_ct_nu'),
        ('upper', 'no-transpose', 'non-unit', make_upper, 'u_nt_nu'),
        ('upper', 'no-transpose', 'unit', make_upper_unit, 'u_nt_u'),
        ('upper', 'transpose', 'non-unit', make_upper, 'u_t_nu'),
        ('upper', 'transpose', 'unit', make_upper_unit, 'u_t_u'),
    ]

    for order in ['row-major', 'column-major']:
        prefix = 'row_major' if order == 'row-major' else 'column_major'

        for uplo, trans, diag, make_A, suffix in configs:
            A = make_A()
            N = A.shape[0]

            # Compute x_input so that the result is X_INIT
            if trans == 'transpose':
                x_input = A.T @ X_INIT
            elif trans == 'conjugate-transpose':
                x_input = A.conj().T @ X_INIT
            else:
                x_input = X_INIT.copy()

            x_out = solve_ctrsv(A, x_input.copy(), uplo, trans, diag)

            # Standard strides for unit-stride layout
            if order == 'row-major':
                sa1, sa2 = N, 1
            else:
                sa1, sa2 = 1, N

            fixture = {
                'order': order,
                'uplo': uplo,
                'trans': trans,
                'diag': diag,
                'N': int(N),
                'x': interleave(x_input),
                'strideX': 1,
                'offsetX': 0,
                'A': layout_matrix(A, order, sa1, sa2, 0),
                'A_mat': mat_to_list(A),
                'LDA': int(N),
                'strideA1': int(sa1),
                'strideA2': int(sa2),
                'offsetA': 0,
                'x_out': interleave(x_out),
            }
            write_fixture(f"{prefix}_{suffix}.json", fixture)


# ---------------------------------------------------------------------------
# Stride / offset / access-pattern fixtures
# ---------------------------------------------------------------------------

def gen_stride_fixtures():
    """Generate stride, offset, and access-pattern fixtures."""

    A = make_upper_unit()
    N = 3

    # Use upper/transpose/unit since the base fixture tests use this combo
    uplo = 'upper'
    trans = 'transpose'
    diag = 'unit'

    x_out_ref = solve_ctrsv(A, X_INIT.copy(), uplo, trans, diag)

    for order in ['row-major', 'column-major']:
        prefix = 'row_major' if order == 'row-major' else 'column_major'
        if order == 'row-major':
            base_sa1, base_sa2 = N, 1
        else:
            base_sa1, base_sa2 = 1, N

        # ------- xp: positive x stride = 2 -------
        sx = 2
        x_buf = np.zeros(N + (N - 1) * (sx - 1), dtype=np.complex64)
        x_out_buf = np.zeros_like(x_buf)
        for i in range(N):
            x_buf[i * sx] = X_INIT[i]
            x_out_buf[i * sx] = x_out_ref[i]

        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(x_buf),
            'strideX': int(sx),
            'offsetX': 0,
            'A': layout_matrix(A, order, base_sa1, base_sa2, 0),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(base_sa1),
            'strideA2': int(base_sa2),
            'offsetA': 0,
            'x_out': interleave(x_out_buf),
        }
        write_fixture(f"{prefix}_xp.json", fixture)

        # ------- xn: negative x stride = -1 -------
        x_neg = np.array(list(reversed(X_INIT)), dtype=np.complex64)
        x_out_neg = np.array(list(reversed(x_out_ref)), dtype=np.complex64)

        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(x_neg),
            'strideX': -1,
            'offsetX': int(N - 1),
            'A': layout_matrix(A, order, base_sa1, base_sa2, 0),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(base_sa1),
            'strideA2': int(base_sa2),
            'offsetA': 0,
            'x_out': interleave(x_out_neg),
        }
        write_fixture(f"{prefix}_xn.json", fixture)

        # ------- oa: matrix offset = 1 (complex element) -------
        oa = 1
        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(X_INIT),
            'strideX': 1,
            'offsetX': 0,
            'A': layout_matrix(A, order, base_sa1, base_sa2, oa),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(base_sa1),
            'strideA2': int(base_sa2),
            'offsetA': int(oa),
            'x_out': interleave(x_out_ref),
        }
        write_fixture(f"{prefix}_oa.json", fixture)

        # ------- ox: vector offset = 1 -------
        pad = np.array([999+999j], dtype=np.complex64)
        x_padded = np.concatenate([pad, X_INIT])
        x_out_padded = np.concatenate([pad, x_out_ref])

        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(x_padded),
            'strideX': 1,
            'offsetX': 1,
            'A': layout_matrix(A, order, base_sa1, base_sa2, 0),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(base_sa1),
            'strideA2': int(base_sa2),
            'offsetA': 0,
            'x_out': interleave(x_out_padded),
        }
        write_fixture(f"{prefix}_ox.json", fixture)

        # ------- sa1_sa2: non-unit matrix strides -------
        # Double the stride (same pattern as dtrsv: strideA1 = 2*N for
        # row-major, so each row has N padding elements)
        if order == 'row-major':
            sa1, sa2 = 2 * N, 2
        else:
            sa1, sa2 = 2, 2 * N

        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(X_INIT),
            'strideX': 1,
            'offsetX': 0,
            'A': layout_matrix(A, order, sa1, sa2, 0),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(sa1),
            'strideA2': int(sa2),
            'offsetA': 0,
            'x_out': interleave(x_out_ref),
        }
        write_fixture(f"{prefix}_sa1_sa2.json", fixture)

        # ------- sa1_sa2n: positive sa1, negative sa2 -------
        # For negative sa2, the columns go in reverse. We need to adjust
        # offsetA so that col 0 starts at the right place.
        neg_sa2 = -sa2
        oa_neg2 = (N - 1) * sa2  # offset to compensate for negative stride
        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(X_INIT),
            'strideX': 1,
            'offsetX': 0,
            'A': layout_matrix(A, order, sa1, neg_sa2, oa_neg2),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(sa1),
            'strideA2': int(neg_sa2),
            'offsetA': int(oa_neg2),
            'x_out': interleave(x_out_ref),
        }
        write_fixture(f"{prefix}_sa1_sa2n.json", fixture)

        # ------- sa1n_sa2: negative sa1, positive sa2 -------
        neg_sa1 = -sa1
        oa_neg1 = (N - 1) * sa1
        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(X_INIT),
            'strideX': 1,
            'offsetX': 0,
            'A': layout_matrix(A, order, neg_sa1, sa2, oa_neg1),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(neg_sa1),
            'strideA2': int(sa2),
            'offsetA': int(oa_neg1),
            'x_out': interleave(x_out_ref),
        }
        write_fixture(f"{prefix}_sa1n_sa2.json", fixture)

        # ------- sa1n_sa2n: both negative -------
        oa_neg12 = (N - 1) * sa1 + (N - 1) * sa2
        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(X_INIT),
            'strideX': 1,
            'offsetX': 0,
            'A': layout_matrix(A, order, neg_sa1, neg_sa2, oa_neg12),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(neg_sa1),
            'strideA2': int(neg_sa2),
            'offsetA': int(oa_neg12),
            'x_out': interleave(x_out_ref),
        }
        write_fixture(f"{prefix}_sa1n_sa2n.json", fixture)


def gen_complex_access_pattern():
    """Complex access pattern: non-unit strides and offsets for both A and x."""

    A = make_upper_unit()
    N = 3
    uplo = 'upper'
    trans = 'transpose'
    diag = 'unit'

    x_out_ref = solve_ctrsv(A, X_INIT.copy(), uplo, trans, diag)

    for order in ['row-major', 'column-major']:
        prefix = 'row_major' if order == 'row-major' else 'column_major'

        # x with stride=3 and offset=2
        sx = 3
        ox_off = 2
        x_buf = np.zeros(ox_off + sx * (N - 1) + 1, dtype=np.complex64)
        x_out_buf = np.zeros_like(x_buf)
        for i in range(N):
            x_buf[ox_off + sx * i] = X_INIT[i]
            x_out_buf[ox_off + sx * i] = x_out_ref[i]

        # A with large strides and offset
        if order == 'row-major':
            sa1, sa2 = 3 * N, 3
        else:
            sa1, sa2 = 3, 3 * N
        oa = 1

        fixture = {
            'order': order,
            'uplo': uplo,
            'trans': trans,
            'diag': diag,
            'N': int(N),
            'x': interleave(x_buf),
            'strideX': int(sx),
            'offsetX': int(ox_off),
            'A': layout_matrix(A, order, sa1, sa2, oa),
            'A_mat': mat_to_list(A),
            'LDA': int(N),
            'strideA1': int(sa1),
            'strideA2': int(sa2),
            'offsetA': int(oa),
            'x_out': interleave(x_out_buf),
        }
        write_fixture(f"{prefix}_complex_access_pattern.json", fixture)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

if __name__ == '__main__':
    print("Generating ctrsv test fixtures...")
    print()
    print("=== Branch fixtures ===")
    gen_branch_fixtures()
    print()
    print("=== Stride/offset fixtures ===")
    gen_stride_fixtures()
    print()
    print("=== Complex access pattern fixtures ===")
    gen_complex_access_pattern()
    print()
    print("Done!")
